mapper.insert:
INSERT INTO ROOM_AMENITY (
    ROOM_SN, AMENITY_SN, REG_DT, MDFCN_DT, RGTR_SN
) VALUES (
    #{roomSn}, #{amenitySn}, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{rgtrSn}
)

mapper.update:
UPDATE ROOM_AMENITY RA
  JOIN ROOM R  ON R.ROOM_SN = RA.ROOM_SN AND R.DEL_YN = 'N'
  JOIN HOUSE H ON H.HOUSE_SN = R.HOUSE_SN AND H.PRTNR_SN = #{prtnrSn} AND H.DEL_YN = 'N'
   SET RA.DEL_YN = 'Y',
       RA.MDFCN_DT = UTC_TIMESTAMP(6),
       RA.MDFR_SN = #{mdfrSn}
 WHERE RA.ROOM_SN = #{roomSn}
   AND RA.DEL_YN = 'N'

   AND RA.AMENITY_SN NOT IN
    #{id}
